/* ===================== 0.15 · ui-blocks.js =====================
   Fast First Encounter block composer. Up to three street elements per block;
   optional north-south river or pedestrian tunnel one level below the street.
   Appended blocks are separated by automatic four-way street intersections. */
const BB=window.RCBlocks;
let BBstate={name:'New block',elements:['store','park'],lower:'river',crossing:'center',mirror:false};
let BBnotes=[]; /* 0.15.1: what the last build moved or narrowed so its stairs fit (shown at the top of the panel) */

function bbEsc(s){return esc(String(s));}
function bbRecipe(){return project.routeNet?.blockComposer?.schema===BB.VERSION?C.clone(project.routeNet.blockComposer.recipe||[]):[];}
function bbElementCount(){return BBstate.elements.length;}
function bbSpec(index=0){return BB.normalizeSpec({id:`block_${String(index+1).padStart(2,'0')}`,name:BBstate.name||`Block ${index+1}`,elements:BBstate.elements,lower:BBstate.lower,crossing:BBstate.crossing,mirror:BBstate.mirror},index);}
function bbCrossDiagram(){const x={left:18,center:50,right:82}[BBstate.crossing]||50,lower=BBstate.lower;return `<div class="bb-diagram"><div class="bb-main-street">MAIN STREET · E ↔ W</div>${lower!=='none'?`<div class="bb-cross ${lower}" style="left:${x}%"><span>${lower==='river'?'RIVER + WALKS':'LOWER WALK TUNNEL'}<br>N ↕ S</span></div><div class="bb-bridge" style="left:${x}%">BRIDGE</div>`:''}<div class="bb-bays"><i>1</i><i>2</i><i>3</i></div></div>`;}
function bbRoadProfile(){return `<div class="bb-road-profile"><span class="walk">SIDEWALK</span><span class="park">PARK</span><span class="drive east">DRIVE →</span><span class="drive west">← DRIVE</span><span class="park">PARK</span><span class="walk">SIDEWALK</span></div><p class="bb-road-note">Every block uses four road lanes: two center driving lanes and one parallel-parking lane against each sidewalk. Marked parking spaces include a clear maneuver buffer at both ends.</p>`;}
function blockBuilderPane(){
  const count=bbElementCount(),generated=bbRecipe(),isGenerated=generated.length>0;
  const presets=Object.entries(BB.PRESETS).map(([id,p])=>`<button class="bb-preset" data-bb-preset="${id}"><strong>${bbEsc(p.label)}</strong><small>${p.elements.length} elements · ${p.lower==='none'?'street only':p.lower+' under bridge'}</small></button>`).join('');
  const elements=Object.entries(BB.ELEMENTS).map(([id,d])=>{const on=BBstate.elements.includes(id),disabled=!on&&count>=3;return `<label class="bb-element ${on?'active':''} ${disabled?'disabled':''}"><input type="checkbox" data-bb-element="${id}" ${on?'checked':''} ${disabled?'disabled':''}><span><strong>${bbEsc(d.label)}</strong><small>${bbEsc(d.side==='near'?'near side / frontage':'far side / public edge')}</small></span></label>`;}).join('');
  const inst=project.routeNet?.blockComposer?.instances||[],list=isGenerated?generated.map((b,i)=>{const notes=inst[i]?.layout?.notes||[];return `<button class="list-card" data-bb-focus="${i}"><span><strong>${bbEsc(b.name||`Block ${i+1}`)}</strong><small>${(b.elements||[]).map(x=>BB.ELEMENTS[x]?.label||x).join(' + ')} · ${b.lower==='none'?'street only':b.lower+' N↕S'}</small>${notes.length?`<small title="${bbEsc(notes.join(' '))}">Adjusted to fit the stairs: ${bbEsc(notes.map(n=>n.replace(/^[^:]*: /,'')).join(' '))}</small>`:''}</span></button>`;}).join(''):'';
  return `<div class="section bb-head"><div class="row"><h2 class="grow">Block Composer</h2><span class="badge">${count}/3</span></div><p>Build one city block quickly, or append blocks into a generated street. Every block can contain <b>1–3 elements</b>. <b>Four-way intersections are inserted automatically between appended blocks.</b></p>${bbCrossDiagram()}${bbRoadProfile()}</div>
  ${BBnotes.length?`<div class="section"><div class="warning"><b>Last build: adjusted so the stairs fit</b><br>${BBnotes.map(bbEsc).join('<br>')}</div></div>`:''}
  <div class="section"><h3>Quick presets</h3><div class="bb-presets">${presets}</div></div>
  <div class="section"><div class="row"><h3 class="grow">Street elements</h3><span class="badge">MAX 3</span></div><div class="bb-elements">${elements}</div><p>${count===3?'Three selected. Deselect one to choose a different element.':'Choose up to three. Their bays are distributed across the block automatically.'}</p></div>
  <div class="section"><h3>Below the street</h3><label>Lower crossing<select id="bbLower"><option value="none" ${BBstate.lower==='none'?'selected':''}>None · ordinary street block</option><option value="river" ${BBstate.lower==='river'?'selected':''}>River + two riverwalks · under street bridge</option><option value="tunnel" ${BBstate.lower==='tunnel'?'selected':''}>Pedestrian walkway tunnel · under street bridge</option></select></label><label>Perpendicular crossing position<select id="bbCrossing"><option value="left" ${BBstate.crossing==='left'?'selected':''}>Left bay</option><option value="center" ${BBstate.crossing==='center'?'selected':''}>Center bay</option><option value="right" ${BBstate.crossing==='right'?'selected':''}>Right bay</option></select></label><label class="check"><input id="bbMirror" type="checkbox" ${BBstate.mirror?'checked':''}>Mirror this block</label><p>The main street always runs <b>east–west</b>. Rivers and lower tunnels run <b>north–south</b>, one pedestrian level below it. The street/sidewalk deck becomes the bridge automatically. Between blocks, a north–south cross street creates a four-way pedestrian intersection with north/south connectors.</p></div>
  <div class="section"><label>Block name<input id="bbName" maxlength="80" value="${bbEsc(BBstate.name)}"></label><label class="check" title="0.15.2 first texture pass: chunky CC0 pictures on the road, sidewalks, shop fronts, park and the lower level. Untick for the plain coloured street."><input type="checkbox" id="bbTextures" ${BBstate.textures!==false?'checked':''}>Street textures (first pass: asphalt, paving, brick fronts, grass)</label><label class="check" title="0.16 preview: every vehicle is one persistent object on the road graph (Vehicle World). The older traffic stays available when unticked."><input type="checkbox" id="bbVehicleWorld" ${(BBstate.vehicleWorld??project.routeNet?.vehicleLoop?.runtime==='world')?'checked':''}>New vehicle runtime (Vehicle World preview)</label><button class="primary block" data-bb-build="new" ${count?'':'disabled'}>Build / load this new block</button><button class="block" style="margin-top:8px" data-bb-build="append" ${count&&isGenerated&&generated.length<6?'':'disabled'}>Append east to generated street</button>${isGenerated?`<p>Current generated recipe: <b>${generated.length}</b> block${generated.length===1?'':'s'}. Append rebuilds the generated recipe, so do your manual fine editing after the block layout is settled.</p>`:'<p>To make a street from blocks, build the first block here. Then return to Blocks and use <b>Append east</b>.</p>'}</div>
  ${isGenerated?`<div class="section"><h3>Generated blocks</h3>${list}</div>`:''}
  <div class="section"><h3>What is automatic</h3><p>Shared pedestrian lanes, <b>four-lane road geometry</b>, two Vehicle Loop driving lanes, marked parallel-parking spaces with front/rear maneuver buffers, parked cars, spawn edges, element activity nodes, lower-level stairs, lower pedestrian lanes, bridge metadata, <b>four-way intersections between blocks</b>, and descriptor-only Encounter hooks are authored with the block.</p></div>`;
}

function bbRememberControls(){const n=$('bbName');if(n)BBstate.name=n.value.trim()||'New block';const l=$('bbLower');if(l)BBstate.lower=l.value;const c=$('bbCrossing');if(c)BBstate.crossing=c.value;const m=$('bbMirror');if(m)BBstate.mirror=m.checked;const tx=$('bbTextures');if(tx)BBstate.textures=tx.checked;const vw=$('bbVehicleWorld');if(vw)BBstate.vehicleWorld=vw.checked;if(BBstate.elements.includes('subway_stairs')&&BBstate.lower==='none')BBstate.lower='tunnel';}
function bbSetPreset(id){const p=BB.PRESETS[id];if(!p)return;BBstate={...BBstate,name:p.label,elements:C.clone(p.elements),lower:p.lower,crossing:p.crossing,mirror:false};renderLeft();}
function bbBuildOptions(name){return {name,assets:[...catalog.values()].filter(a=>a.category==='character').map(C.clone),characters:C.clone(project.routeNet?.characters||[]),vehicleLoop:bbVehicleLoop(),...(project.routeNet?.vehicleTraffic?{vehicleTraffic:C.clone(project.routeNet.vehicleTraffic)}:{}),textures:BBstate.textures!==false};}
/* 0.16: the Vehicle World switch rides on vehicleLoop.runtime; authored traffic (routeNet.vehicleTraffic) is carried through every rebuild */
function bbVehicleLoop(){const vl=C.clone(project.routeNet?.vehicleLoop||BB.DEFAULT_VEHICLE_LOOP),on=BBstate.vehicleWorld??vl.runtime==='world';if(on)vl.runtime='world';else delete vl.runtime;return vl;}
async function bbApply(recipe,name,{preserveCity=false}={}){try{const bundle=BB.buildBundle(recipe,bbBuildOptions(name));if(preserveCity&&project.cityStructure)bundle.project.cityStructure=C.clone(project.cityStructure);await applyBundle(bundle,{dirtyAfter:true});pane='blocks';activeStory=BB.STREET;selection={kind:'room',id:project.rooms.find(r=>(r.story||0)===BB.STREET)?.id||project.rooms[0].id};roomId=selection.id;fit();refresh();const notes=(project.routeNet?.blockComposer?.instances||[]).flatMap(i=>i.layout?.notes||[]);BBnotes=notes;renderLeft();toast(`Generated ${recipe.length} block${recipe.length===1?'':'s'} · ${Math.max(0,recipe.length-1)} intersection${recipe.length===2?'':'s'} · ${recipe.reduce((n,b)=>n+(b.elements?.length||0),0)} street elements.${notes.length?' Adjusted so the stairs fit: '+notes.join(' '):''}`,notes.length?14000:4800);}catch(e){toast('Block build failed: '+e.message,9000);}}
function bbBuildNew(){bbRememberControls();const spec=bbSpec(0),run=()=>bbApply([spec],`First Encounter · ${spec.name}`);if(dirty||project.cityStructure)ask('Build a new generated block?','This replaces the current working project, including its City Structure declarations. Save first to keep them.',run,'Build new block');else run();}
function bbAppend(){bbRememberControls();const recipe=bbRecipe();if(!recipe.length){toast('Build the first Block Composer block before appending.');return;}if(recipe.length>=6){toast('This prototype supports up to six generated blocks in one street.');return;}const spec=bbSpec(recipe.length);recipe.push(spec);ask('Append this block east?','The generated street recipe will be rebuilt. Manual geometry edits are not carried into the regenerated blocks. City Structure declarations are retained by exact ID; inspect City afterward for unresolved bindings. No automatic remapping is performed.',()=>bbApply(recipe,`First Encounter · ${recipe.length} generated blocks`,{preserveCity:true}),'Append block');}
function bbFocus(index){const inst=project.routeNet?.blockComposer?.instances?.[index];if(!inst)return;selectStory(BB.STREET);setMode('plan');focusMap({x:inst.origin.x+BB.W/2,y:24},2.25,BB.STREET);toast(`${inst.name}: ${(inst.elements||[]).map(x=>BB.ELEMENTS[x]?.label||x).join(' + ')}`);}

HOOKS.leftRender.push(el=>{if(pane==='blocks'){el.innerHTML=blockBuilderPane();el.scrollTop=0;}});
HOOKS.click.push((e,b)=>{if(b.dataset.bbPreset){bbSetPreset(b.dataset.bbPreset);return true;}if(b.dataset.bbBuild==='new'){bbBuildNew();return true;}if(b.dataset.bbBuild==='append'){bbAppend();return true;}if(b.dataset.bbFocus!==undefined){bbFocus(Number(b.dataset.bbFocus));return true;}return false;});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.bbElement){const id=el.dataset.bbElement;if(el.checked){if(BBstate.elements.length>=3){el.checked=false;toast('A block can contain at most three elements.');return;}BBstate.elements.push(id);}else BBstate.elements=BBstate.elements.filter(x=>x!==id);if(BBstate.elements.includes('subway_stairs')&&BBstate.lower==='none')BBstate.lower='tunnel';renderLeft();return;}if(['bbLower','bbCrossing','bbMirror'].includes(el.id)){bbRememberControls();renderLeft();}});
document.addEventListener('input',e=>{if(e.target.id==='bbName')BBstate.name=e.target.value;});
if($('blockBtn'))$('blockBtn').onclick=()=>{pane='blocks';renderLeft();};
EXT.blocks={get state(){return C.clone(BBstate);},setPreset:bbSetPreset,build:bbBuildNew,append:bbAppend,recipe:bbRecipe};
